inline const SuitAsset* findSuitAsset(const char* code) {
    for (const SuitAsset& a : kSuitAssets) {
        const char* x = a.code;
        const char* y = code;
        while (*x && *x == *y) ++x, ++y;
        if (*x == *y) return &a;
    }
    return nullptr;
}

